-- PBI-005: historial de cada entrada y salida de stock. El saldo vive en productos.StockActual.
create table if not exists public.movimientos_stock (
  "Id_Movimientos_Stock" integer generated by default as identity primary key,
  "Id_Productos" integer not null references public.productos("Id_Productos") on delete restrict,
  "Fecha" timestamp not null default now(),
  "Tipo" varchar(10) not null check ("Tipo" in ('Entrada', 'Salida')),
  "Origen" varchar(30) not null,
  "Cantidad" numeric(18,0) not null check ("Cantidad" > 0),
  "StockResultante" numeric(18,0) not null check ("StockResultante" >= 0),
  "Id_Referencia" integer null,
  "Observacion" varchar(250) null,
  "Id_Usuarios" integer not null references public.usuarios("Id_Usuarios") on delete restrict
);

create index if not exists ix_movimientos_stock_producto on public.movimientos_stock ("Id_Productos", "Fecha");
